<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap.php';
Auth::requireRole('customer');

$pdo = db();
$stmt = $pdo->prepare(
    'SELECT o.id,o.order_number,o.subtotal,o.delivery_fee,o.total,o.status,o.created_at,
            (SELECT COUNT(*) FROM order_items oi WHERE oi.order_id=o.id) item_count
     FROM orders o WHERE o.customer_id=? ORDER BY o.id DESC'
);
$stmt->execute([(int)Auth::userId()]);
$orders = $stmt->fetchAll();
function customerOrderBadge(string $status): string {
    return match ($status) {
        'completed' => 'success', 'cancelled','refunded' => 'danger', 'shipped' => 'info', default => 'warning'
    };
}
?>

